function.arguments:
{"sql": "SELECT COUNT(*) FROM `bigquery-public-data.libraries_io.repository_dependencies` rd
WHERE rd.repository_name_with_owner NOT IN (
  SELECT name_with_owner FROM `bigquery-public-data.libraries_io.repositories`
)"}

{"sql": "SELECT p.id, p.name, p.platform, p.language, p.repository_id, p.updated_timestamp
FROM `bigquery-public-data.libraries_io.projects` p
WHERE p.repository_id IN (
  SELECT DISTINCT rd.repository_id
  FROM `bigquery-public-data.libraries_io.repository_dependencies` rd
  WHERE rd.dependency_project_name IN (
    'FeatureToggle', 'flipper', 'flip', 'feature', 'org.togglz:togglz-core'
  )
)
LIMIT 10"}

{"sql": "SELECT pr.repository_id, pr.repository_name_with_owner, pr.repository_host_type, pr.repository_size, pr.repository_language, pr.repository_fork_source_name_with_owner, pr.repository_updated_timestamp
FROM `bigquery-public-data.libraries_io.projects_with_repository_fields` pr
WHERE pr.repository_id IN (
  SELECT DISTINCT rd.repository_id
  FROM `bigquery-public-data.libraries_io.repository_dependencies` rd
  WHERE rd.dependency_project_name IN (
    'FeatureToggle', 'flipper', 'flip', 'feature', 'org.togglz:togglz-core'
  )
)"}
